import org.jsoup.Jsoup;
import org.jsoup.nodes.Document;

public class Main {
    public static void main(String[] args) throws Exception {
        String url = "http://example.com";
        Document doc = Jsoup.connect(url).get();

        System.out.println("Title: " + doc.title());
        System.out.println("Text: " + doc.text().trim());

        int footerCount = 0;
        for (var link : doc.select("link[rel=stylesheet][href*=\"footer\"]")) {
            if (link.attr("href").contains("footer")) {
                footerCount++;
            }
        }

        System.out.println("Footer Count: " + footerCount);
    }
}
